// A flow is the chain of work one user interaction starts: the event, the
// timers and promise callbacks it schedules, the commits they cause. The
// interceptors carry the current flow into every callback they wrap, and the
// logging layer tags events with it.
let currentFlow = null;
let nextId = 1;

class Flow {
  constructor(name, parent) {
    this.id = nextId++;
    this.name = name;
    this.parent = parent;
    this.data = null;
  }

  fullName() {
    return this.parent ? `${this.parent.fullName()}/${this.name}` : this.name;
  }
}

const INTERACTION_EVENTS = new Set(["click", "keydown", "input", "beforeinput", "focusin", "mouseover", "submit", "scroll"]);

const FlowContext = {
  current() {
    return currentFlow;
  },
  bind(flow, callback) {
    return function () {
      const previous = currentFlow;
      currentFlow = flow;
      try {
        return callback.apply(this, arguments);
      } finally {
        currentFlow = previous;
      }
    };
  },
  onEvent(event) {
    if (INTERACTION_EVENTS.has(event.type)) {
      currentFlow = new Flow(event.type, null);
    }
  },
  onNavigation(url) {
    currentFlow = new Flow(`nav:${url}`, currentFlow);
  },
  start(name) {
    currentFlow = new Flow(name, currentFlow);
    return currentFlow;
  },
};

export default FlowContext;
