// Runs callbacks inside a try/catch that reports to ErrorPubSub, the way
// every event handler, timer and scheduled callback on the reference site
// runs inside an error guard.
import ErrorPubSub from "ErrorPubSub";

let depth = 0;
const nameStack = [];

export function applyWithGuard(fn, context, args, options) {
  depth++;
  nameStack.push(options?.name ?? fn.name ?? "anonymous");
  try {
    return fn.apply(context, args);
  } catch (error) {
    ErrorPubSub.reportError(error, { name: nameStack[nameStack.length - 1], depth });
    if (options?.rethrow) {
      throw error;
    }
    return undefined;
  } finally {
    nameStack.pop();
    depth--;
  }
}

export function guard(fn, name) {
  if (fn.__guarded) {
    return fn.__guarded;
  }
  const guarded = function () {
    return applyWithGuard(fn, this, arguments, { name });
  };
  fn.__guarded = guarded;
  return guarded;
}

export function inGuard() {
  return depth > 0;
}
